import{_ as p,l as r,o as e,c as o,v as l,p as n,x as i,d,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"DualPipe","description":"","frontmatter":{"title":"DualPipe","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dualpipe.md","filePath":"llm/dualpipe.md","lastUpdated":1789023840000}'),u={name:"llm/dualpipe.md"};function c(P,a,B,m,E,_){const t=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=l('<h1 id="dualpipe" tabindex="-1">DualPipe <a class="header-anchor" href="#dualpipe" aria-label="Permalink to &quot;DualPipe&quot;">​</a></h1><div class="epigraph"><p>两套微批沿相反方向走同一组设备，正向与反向的通信与计算互相遮挡，流水线两端不再是注定的空闲段。</p><footer>—— DeepSeek-V3 技术报告中的 DualPipe 调度</footer></div><p><a href="/llm/zero-bubble-pipeline">上一课</a>在单向流水上拆 \\(B/W\\)。设备排成一条线时，第 1 段与第 \\(P\\) 段在预热和冲刷里仍然更闲，通信方向也单一。DeepSeek-V3 用 DualPipe：把流水看成可以同时跑正向批次与反向批次的双向管道。本课不重讲 \\(B/W\\) 拆分。缺口是双向日历如何与已经学过的 1F1B / ZB 区分，以及它要求的实现前提（两份在飞状态、通信反向）。重叠课会把同一思想用到 TP；本课只谈流水这条轴。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单向 PP 的气泡即使在稳态被 ZB 压掉，pipeline 的两端在 batch 边界仍要等。长窗口、小 \\(M\\) 时，边界空拍占比重新变大。双向调度让一组微批从阶段 1 走向 \\(P\\)，另一组从 \\(P\\) 走向 1，一台设备在「给正向做 \\(F\\)」的同时可以用另一套缓冲给反向做 \\(B\\)。这要求激活与梯度的缓冲翻倍，并要求网络同时打两个方向而不互相排队。</p><p>DeepSeek 的报告把它写成与 MoE、FP8 一起的系统选择。本课只抽取调度语义，不把专家并行写进来当主角——MoE All-to-All 在后课。</p><h3 id="与交错虚阶段的差别" tabindex="-1">与交错虚阶段的差别 <a class="header-anchor" href="#与交错虚阶段的差别" aria-label="Permalink to &quot;与交错虚阶段的差别&quot;">​</a></h3><p>交错是同一方向上多层映射到一卡。DualPipe 是两个方向的流量共享卡。两者都能填洞，内存账不同：交错加虚阶段激活；双向加第二套在飞微批。不要在配置里用同一个 <code>pp_schedule</code> 字符串表示两件事。</p><p><span class="marginnote">双向不意味着数学上变成非因果。两条流仍是各自的因果前向与对应反向，只是设备日历交织。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护两套微批队列。偶数全局步以 1→\\(P\\) 为主方向，奇数步对开，或在同一全局 batch 内同时注入两端（实现依赖框架）。每阶段的内核顺序写成：计算当前方向的 \\(F\\) 或 \\(B\\)，把通信 post 到反向流量的流上。DeepSeek-V3 强调计算与跨阶段通信重叠；若 NCCL 无法双向充分并行，日历会退化为「看起来双向、实际仍排队」。</p><p>对拍实验：相同 FLOPs 与数据，DualPipe 与 1F1B 的损失应对齐；吞吐差应能用气泡公式解释，而不是静默改了 batch 语义。梯度累积步数要对两套队列对称，否则优化器看到的 token 数抖动。</p><h3 id="内存与重计算" tabindex="-1">内存与重计算 <a class="header-anchor" href="#内存与重计算" aria-label="Permalink to &quot;内存与重计算&quot;">​</a></h3><p>缓冲翻倍迫使更激进的重计算或更小微批。微批太小会打不满 <a href="/llm/tensor-parallel">张量并行</a> 的 GEMM，又把收益吐给 TP。应先定 TP 度与微批下限，再开 DualPipe，而不是先开双向再发现矩阵乘变碎。</p><p><span class="marginnote">检查点必须记录两套在飞状态或保证边界上没有在飞，否则故障恢复会从错误的微批重放。后课异步检查点要知道这一点。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>流水气泡本质是依赖方向单一。引入反向流量后，关键路径上的等待被另一条独立依赖链的计算填满。利用率提高，来自并发度而不是减少工作量。通信体积仍按激活形状 × 两套流增加，InfiniBand 过载时 DualPipe 会先于 1F1B 饱和。拓扑感知放置课会要求这两条流走的链路不要挤在同一条胖树的过订阅切面上。</p>',17)),(e(),n(h,null,{default:i(()=>[s(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E9%98%B6%E6%AE%B5%201%22%5D%20--%3E%7C%22%E6%B5%81%E7%94%B2%20%E5%89%8D%E5%90%91%22%7C%20B%5B%22%E9%98%B6%E6%AE%B5%20k%22%5D%0A%20%20B%20--%3E%7C%22%E6%B5%81%E7%94%B2%22%7C%20C%5B%22%E9%98%B6%E6%AE%B5%20P%22%5D%0A%20%20C%20--%3E%7C%22%E6%B5%81%E4%B9%99%20%E5%8F%8D%E5%90%91%E6%B3%A8%E5%85%A5%22%7C%20B%0A%20%20B%20--%3E%7C%22%E6%B5%81%E4%B9%99%22%7C%20A%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>DualPipe 实现成本高，小 \\(P\\) 时收益不如加 \\(M\\)。它不替代 ZB：有的系统两者叠加，有的只选其一。不要与数据并行的双向 All-Reduce 术语混淆。下一课把「通信躲进计算」从流水边界推广到 TP/DP 的集合通信，成为所有并行轴共用的手法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲 \\(B/W\\)；只补双向微批流共享设备日历。</li><li>第二套在飞状态换两端气泡；网络必须真能双向并行。</li><li>损失应对拍 1F1B；微批下限受 TP GEMM 约束。</li><li>检查点要知道双流状态。</li><li>出处：DeepSeek-AI, <em>DeepSeek-V3 Technical Report</em>；对照 Narayanan 等 Megatron 流水与 Qi 等零气泡。</li></ul>',4))])}const b=p(u,[["render",c]]);export{f as __pageData,b as default};
